<script lang="ts">
 import {onMount} from 'svelte';import {api,uploadTo} from './api';import type {Row} from './types';
 let {companies,company,orders=[]}:{companies:Row[];company:string;orders:Row[]}=$props();
 let data:any=$state(null),detail:any=$state(null),form:any=$state(null),busy=$state(false),error=$state(''),notice=$state(''),review=$state(''),search=$state(''),category=$state('Buyer email'),stockForm:any=$state(null),option:any=$state(null),production:any=$state(null),printMode=$state('indent'),printPiece=$state(0);
 const fields=[['brand','Brand'],['request_date','Request date','date'],['buyer_requested_date','Buyer requested date','date'],['buyer_required_date','Buyer required date','date'],['plan_date','Plan date','date'],['email_date','Buyer email date','date'],['email_subject','Buyer email subject'],['sample_type','Sample type','option'],['est','EST number (numbers only)'],['buyer_style','Buyer style number'],['buyer_spec','Buyer specification number'],['product','Product','option'],['description','Description'],['fit','Block / fit'],['factory','Sample production factory','option'],['season','Season','option'],['year','Season year'],['order_id','Linked production PO (optional)','order'],['buyer_po','Buyer PO reference (if available)'],['pattern_status','Pattern status','pattern'],['material_id','Required ETF / ESF','material'],['length_metres','Fabric required (metres)'],['alternate_material_id','Alternate ETF / ESF (if required)','material'],['alternate_reference','Alternate reference'],['fabric_in_date','Fabric-in date','date'],['copy_sample_id','Copy from indent number'],['copy_purpose','Sample to copy — purpose','purpose'],['cad_reference','CAD reference'],['spec_reference','Specification reference'],['spec_date','Specification date','date'],['spec_signed','Specification signed by'],['remake_indent_id','Remake of indent number'],['special_remarks','Special remarks'],['finishing_remarks','Finishing remarks'],['embroidery','Embroidery'],['washing','Washing']];
 const productionFields=[['pattern_by','Pattern by'],['cut_by','Cut by'],['sample_maker','Sample maker'],['pattern_plan_date','Pattern ready — plan','date'],['allocation_plan_date','Cutting allocation — plan','date'],['sewing_plan_date','Sewing handover — plan','date'],['fabric_update_date','Fabric ready date','date'],['trims_update_date','Trims ready date','date'],['style_update_date','Style ready date','date'],['readiness_note','Readiness remarks'],['handover_dc','Handover DC'],['enclosures','Enclosures: cut pattern / counter sample / audit sheet']];
 const bomFields=[['component','Component'],['reference','Article / reference'],['quantity','Quantity'],['unit','Unit'],['colour','Colour'],['size','Size'],['ticket','Thread ticket'],['thread_position','Top / bobbin'],['shade','Shade number'],['placement','Placement'],['remarks','Remarks']];
 const groups=['Pocketing','Fusing','Sewing trims','Labels','Finishing','Value additions'];
 const label=(key:string)=>fields.find(f=>f[0]===key)?.[1]||productionFields.find(f=>f[0]===key)?.[1]||key.replaceAll('_',' ');
 const material=(id:any)=>data?.materials.find((m:any)=>String(m.id)===String(id))?.code||id;
 let records=$derived((data?.records||[]).filter((r:any)=>(!company||String(r.company_id)===company)&&(!search||JSON.stringify(r).toLowerCase().includes(search.toLowerCase()))));
 let printPieces=$derived(detail?.pieces.filter((p:any)=>!printPiece||p.id===printPiece)||[]);
 let layoutPages=$derived.by(()=>{const list=[{group:'Fabric',component:'Primary fabric',reference:material(detail?.record.profile.material_id)},...(detail?.record.bom||[])];const pages=[];for(let i=0;i<Math.max(1,list.length);i+=6)pages.push(list.slice(i,i+6));return pages});
 async function load(){data=await api('/sample-requests')}
 async function run(work:()=>Promise<void>){if(busy)return;busy=true;error='';notice='';try{await work()}catch(e){error=(e as Error).message}finally{busy=false}}
 onMount(()=>{run(load)});
 function fresh(){if(!company&&companies.length>1){error='Select a workspace company before creating a request.';return}form={company_id:Number(company||companies[0]?.id),buyer_id:'',profile:Object.fromEntries(fields.map(f=>[f[0],f[2]==='date'&&f[0]==='request_date'?new Date().toLocaleDateString('en-CA'):''])),variants:[{size:'',colour:'',quantity:1}],bom:[]}}
 async function open(id:number){await run(async()=>{detail=await api('/sample-requests/'+id);review='';production=null;form=null;category=data.can_audit?'Audit sheet':!data.can_edit&&data.can_pattern?'CAD':'Buyer email'})}
 function copyRequest(){const source=structuredClone($state.snapshot(detail.record));form={company_id:source.company_id,buyer_id:source.buyer_id,profile:{...source.profile,copy_sample_id:String(detail.pieces[0]?.id||''),remake_indent_id:''},variants:source.variants,bom:source.bom};detail=null}
 function edit(){form=structuredClone($state.snapshot(detail.record));detail=null}
 async function save(action:string){await run(async()=>{const result=await api('/sample-requests'+(form.id?'/'+form.id:''),{company_id:Number(form.company_id),buyer_id:Number(form.buyer_id),profile:form.profile,variants:form.variants,bom:form.bom,version:form.version,action});form=null;await load();detail=await api('/sample-requests/'+result.id);notice=action==='submit'?'Sent to MD. Sampling receives it after approval.':'Draft saved. Add attachments before submitting.'})}
 async function decide(action:string){await run(async()=>{await api('/sample-requests/'+detail.record.id,{version:detail.record.version,action,note:review});detail=await api('/sample-requests/'+detail.record.id);await load()})}
 async function pieceAction(piece:any,action:string,result=''){await run(async()=>{await api('/sample-indents/'+piece.id,{version:piece.version,action,result,note:review,production:production?.values});detail=await api('/sample-requests/'+detail.record.id);production=null;await load()})}
 function opts(kind:string,cid:any){return [...new Set([...(data?.defaults[kind]||[]),...(data?.options||[]).filter((o:any)=>o.kind===kind&&o.company_id===Number(cid)).map((o:any)=>o.label)])] as string[]}
 async function addOption(){await run(async()=>{await api('/sample-options',{...option,company_id:Number(form.company_id)});await load();form.profile[option.kind]=option.label;option=null})}
 async function upload(event:Event){const input=event.target as HTMLInputElement;const files=Array.from(input.files||[]);await run(async()=>{for(const file of files)await uploadTo('/sample-requests/'+detail.record.id+'/files?category='+encodeURIComponent(category),file);detail=await api('/sample-requests/'+detail.record.id)});input.value=''}
 async function stockSave(){await run(async()=>{await api('/sample-stock',stockForm);stockForm=null;await load();if(detail)detail=await api('/sample-requests/'+detail.record.id);notice='Stock movement recorded.'})}
 function print(kind:string,id=0){printMode=kind;printPiece=id;setTimeout(()=>window.print(),50)}
</script>
<section class="samples">
 <header><div><p class="eyebrow">BUYER REQUEST → MD → SAMPLING → AUDIT → HANDOVER</p><h2>Sample indents</h2><p>One indent per garment. Numbers are assigned after MD approval.</p></div><div class="actions"><button class="button secondary" disabled={busy} onclick={()=>run(load)}>Refresh</button>{#if data?.can_edit}<button class="button primary" disabled={busy} onclick={fresh}>New sample request</button>{/if}{#if data?.can_stock}<button class="button secondary" onclick={()=>stockForm={company_id:Number(company||companies[0]?.id),material_id:'',metres:'',reference:''}}>Receive sample fabric</button>{/if}</div></header>
 {#if error}<div class="form-error" role="alert">{error}</div>{/if}{#if notice}<p role="status">{notice}</p>{/if}
 <label class="search">Search request, style or buyer<input bind:value={search} placeholder="Search sample requests"/></label>
 <div class="table-scroll"><table><thead><tr><th>Request</th><th>Buyer / style</th><th>Plan date</th><th>Status</th><th>Pieces</th><th></th></tr></thead><tbody>{#each records as r}<tr><td>SR-{r.id}</td><td>{r.buyer}<small>{r.profile.buyer_style} · EST {r.profile.est}</small></td><td>{r.profile.plan_date||'—'}</td><td><strong>{r.status}</strong></td><td>{r.pieces||'Pending approval'}</td><td><button class="text-button" disabled={busy} onclick={()=>open(r.id)}>Open</button></td></tr>{:else}<tr><td colspan="6">No sample requests in your current access.</td></tr>{/each}</tbody></table></div>
 {#if data?.stock.length}<details><summary>Sample fabric balances</summary><div class="table-scroll"><table><thead><tr><th>Fabric</th><th>Metres remaining</th></tr></thead><tbody>{#each data.stock.filter((s:any)=>!company||String(s.company_id)===company) as s}<tr><td>{s.code}</td><td>{s.metres}</td></tr>{/each}</tbody></table></div></details>{/if}
</section>
{#if form}
 <div class="sample-overlay"><div role="dialog" aria-modal="true" aria-label="Sample request" tabindex="-1" class="sample-dialog"><header><div><h2>{form.id?'Edit request SR-'+form.id:'Generate sample indent'}</h2></div><button disabled={busy} class="button secondary" onclick={()=>{form=null;option=null}}>Close</button></header>
 {#if error}<div class="form-error" role="alert">{error}</div>{/if}
 <div class="form-grid"><label>Buyer<select bind:value={form.buyer_id}><option value="">Choose buyer</option>{#each data.buyers.filter((b:any)=>b.company_id===Number(form.company_id)) as b}<option value={b.id}>{b.name}</option>{/each}</select></label>
 {#each fields as [key,title,type]}<label>{title}{#if type==='option'}<div class="option-line"><select bind:value={form.profile[key]}><option value="">Select…</option>{#each opts(key,form.company_id) as o}<option>{o}</option>{/each}</select><button class="button secondary" title={'Add '+title} onclick={()=>option={kind:key,label:''}}>+</button></div>{:else if type==='order'}<select bind:value={form.profile[key]} onchange={()=>{const o=orders.find(o=>String(o.id)===form.profile.order_id);if(o){form.buyer_id=o.buyer_id;form.profile.buyer_po=o.po}}}><option value="">No production PO</option>{#each orders.filter(o=>o.company_id===Number(form.company_id)&&(!form.buyer_id||o.buyer_id===Number(form.buyer_id))) as o}<option value={String(o.id)}>{o.po}</option>{/each}</select>{:else if type==='material'}<select bind:value={form.profile[key]}><option value="">Select…</option>{#each data.materials.filter((m:any)=>m.company_id===Number(form.company_id)) as m}<option value={String(m.id)}>{m.code}</option>{/each}</select>{:else if type==='pattern'||type==='purpose'}<select bind:value={form.profile[key]}><option value="">Select…</option>{#each (type==='pattern'?['New','Modified','Existing']:['Style only','Specification only','Style and specification','Construction / make only']) as o}<option>{o}</option>{/each}</select>{:else}<input type={type==='date'?'date':'text'} bind:value={form.profile[key]} inputmode={key==='est'?'numeric':'text'}/>{/if}</label>{/each}
 <label class="wide">Buyer email message<textarea rows="5" bind:value={form.profile.email_message} placeholder="Paste the buyer's message. Upload supporting documents after saving."></textarea></label></div>
 {#if option}<div class="inline-editor"><label>New {label(option.kind)}<input bind:value={option.label} maxlength="100"/></label><button class="button primary" disabled={busy||!option.label.trim()} onclick={addOption}>Add option</button><button class="button secondary" onclick={()=>option=null}>Cancel</button></div>{/if}
 <h3>Sizes, colours and pieces</h3><p>Each piece receives its own number and print sheet. M × 2 + XL × 1 = 3 indents.</p>
 {#each form.variants as v,i}<div class="variant"><label>Size<input bind:value={v.size}/></label><label>Colour<input bind:value={v.colour}/></label><label>Quantity<input type="number" min="1" max="100" step="1" bind:value={v.quantity}/></label><button class="button secondary" disabled={form.variants.length===1} onclick={()=>form.variants.splice(i,1)}>Remove</button></div>{/each}<button class="button secondary" onclick={()=>form.variants.push({size:'',colour:'',quantity:1})}>Add size / colour</button>
 <h3>Sample BOM</h3>{#if !form.bom.length}<p>No components added. Click Add component to add only what you need.</p>{/if}
 {#each form.bom as b,i}<div class="bom-row"><label>Group<select bind:value={b.group}>{#each groups as g}<option>{g}</option>{/each}</select></label>{#each bomFields as [key,title]}<label>{title}<input bind:value={b[key]}/></label>{/each}<button class="text-button" onclick={()=>form.bom.splice(i,1)}>Remove component</button></div>{/each}<button class="button secondary" onclick={()=>form.bom.push({group:'Sewing trims',component:''})}>Add component</button>
 <footer><button class="button secondary" disabled={busy} onclick={()=>save('save')}>{busy?'Saving…':'Save draft'}</button><button class="button primary" disabled={busy} onclick={()=>save('submit')}>Submit to MD</button></footer></div></div>
{/if}
{#if detail}
 <div class="sample-overlay"><div role="dialog" aria-modal="true" aria-label="Sample request details" tabindex="-1" class="sample-dialog"><header><div><p class="eyebrow">REQUEST SR-{detail.record.id} · {detail.record.status}</p><h2>{detail.record.profile.buyer_style} · EST {detail.record.profile.est}</h2></div><button class="button secondary" disabled={busy} onclick={()=>{detail=null;production=null}}>Close</button></header>
 {#if error}<div class="form-error" role="alert">{error}</div>{/if}
 <div class="actions">{#if data.can_edit}<button class="button secondary" onclick={copyRequest}>Copy as new request</button>{/if}{#if ['Draft','Changes requested'].includes(detail.record.status)&&data.can_edit}<button class="button primary" onclick={edit}>Edit / submit</button>{/if}{#if detail.pieces.length}<button class="button secondary" onclick={()=>print('indent')}>Print all indents</button><button class="button secondary" onclick={()=>print('layout')}>Print swatch layout</button>{/if}</div>
 {#if detail.record.review_note}<p><strong>MD review:</strong> {detail.record.review_note}</p>{/if}
 <details open><summary>Request details</summary><div class="details-grid">{#each Object.entries(detail.record.profile) as [key,value]}{#if value}<div><strong>{label(key)}</strong><span>{key.includes('material_id')?material(value):String(value)}</span></div>{/if}{/each}</div></details>
 <h3>Requested sizes and colours</h3><div class="table-scroll"><table><thead><tr><th>Size</th><th>Colour</th><th>Pieces</th></tr></thead><tbody>{#each detail.record.variants as v}<tr><td>{v.size}</td><td>{v.colour}</td><td>{v.quantity}</td></tr>{/each}</tbody></table></div>
 <details><summary>Review sample BOM ({detail.record.bom.length} components)</summary><div class="table-scroll"><table><thead><tr><th>Group / component</th><th>Reference</th><th>Quantity / unit</th><th>Details</th></tr></thead><tbody>{#each detail.record.bom as b}<tr><td>{b.group} · {b.component}</td><td>{b.reference||'—'}</td><td>{b.quantity||'—'} {b.unit||''}</td><td>{[b.colour,b.size,b.ticket,b.thread_position,b.shade,b.placement,b.remarks].filter(Boolean).join(' · ')}</td></tr>{/each}</tbody></table></div></details>
 {#if detail.record.status==='Submitted'&&data.can_approve}<div class="review"><label>MD review note<textarea bind:value={review}></textarea></label><button class="button primary" disabled={busy} onclick={()=>decide('approve')}>Approve and generate indents</button><button class="button secondary" disabled={busy||!review.trim()} onclick={()=>decide('return')}>Return for changes</button></div>{/if}
 <h3>Documents and images</h3><p>Files remain private to users with access to this request.</p><ul>{#each detail.files as f}<li><a href={'/api/sample-files/'+f.id}>{f.category}: {f.name}</a></li>{:else}<li>No documents uploaded.</li>{/each}</ul>
 {#if detail.record.status!=='Submitted'&&((data.can_edit&&detail.record.status!=='Approved')||detail.record.status==='Approved'&&(data.can_produce||data.can_audit||data.can_pattern))}<div class="variant"><label>Document category<select bind:value={category}>{#each ['Buyer email','Buyer specification','Sample to copy','CAD','Labels','Audit sheet','Other'] as c}<option>{c}</option>{/each}</select></label><label>Upload files (10 MB each)<input type="file" multiple disabled={busy} onchange={upload} accept=".eml,.pdf,.docx,.xlsx,.csv,.txt,.png,.jpg,.jpeg,.dxf,.zip"/></label></div>{/if}
 <h3>Individual indents</h3>{#each detail.pieces as piece}<article class="piece"><header><div><h3>#{piece.id} · {piece.size} · {piece.colour}</h3><strong>{piece.status}</strong></div><button class="button secondary" onclick={()=>print('indent',piece.id)}>Print #{piece.id}</button></header><div class="details-grid">{#each Object.entries(piece.production) as [key,value]}{#if value}<div><strong>{label(key)}</strong><span>{String(value)}</span></div>{/if}{/each}</div><div class="actions">
 {#if data.can_produce&&!['Handed over','Rejected'].includes(piece.status)}<button class="button secondary" onclick={()=>production={piece,values:{...piece.production}}}>Plan / readiness / handover details</button>{/if}
 {#if data.can_stock&&!['Handed over','Rejected'].includes(piece.status)}<button class="button secondary" onclick={()=>stockForm={company_id:detail.record.company_id,material_id:detail.record.profile.alternate_material_id||detail.record.profile.material_id,indent_id:piece.id,metres:'',reference:''}}>Issue sample fabric</button>{/if}
 {#if data.can_pattern&&piece.status==='Ready'}<button class="button primary" disabled={busy} onclick={()=>pieceAction(piece,'pattern')}>Pattern completed</button>{/if}
 {#if data.can_produce&&piece.status==='Pattern ready'}<button class="button primary" disabled={busy} onclick={()=>pieceAction(piece,'cut')}>Cutting completed</button>{/if}
 {#if data.can_produce&&['Cut','Rework'].includes(piece.status)}<button class="button primary" disabled={busy} onclick={()=>pieceAction(piece,'sew')}>Sewing completed → QA</button>{/if}
 {#if data.can_audit&&piece.status==='Awaiting audit'}<label>Audit remarks<textarea bind:value={review}></textarea></label>{#each ['Approved','Rework','Rejected'] as result}<button class="button secondary" disabled={busy} onclick={()=>pieceAction(piece,'audit',result)}>{result}</button>{/each}{/if}
 {#if data.can_produce&&piece.status==='Approved'}<button class="button primary" disabled={busy} onclick={()=>pieceAction(piece,'handover')}>Confirm handover</button>{/if}</div></article>{:else}<p>Indent numbers are generated after MD approval.</p>{/each}
 {#if production}<div class="inline-editor production"><h3>Plan and readiness · #{production.piece.id}</h3><div class="form-grid">{#each productionFields as [key,title,type]}<label>{title}<input type={type==='date'?'date':'text'} bind:value={production.values[key]}/></label>{/each}</div><button class="button primary" disabled={busy} onclick={()=>pieceAction(production.piece,'plan')}>Save production details</button><button class="button secondary" onclick={()=>production=null}>Cancel</button></div>{/if}
 <h3>Fabric issues</h3>{#each detail.issues as i}<p><strong>SDC-{String(i.id).padStart(7,'0')}</strong> · Indent #{i.indent_id} · {i.code} · {Math.abs(Number(i.metres))} m</p>{:else}<p>No fabric issues recorded.</p>{/each}
 <details><summary>History</summary>{#each detail.history as h}<p>{new Date(h.created_at).toLocaleString()} · {h.actor} · {h.action}</p>{/each}</details>
 </div></div>
{/if}
{#if stockForm}<div class="sample-overlay top"><div role="dialog" aria-modal="true" aria-label="Sample fabric stock" tabindex="-1" class="sample-dialog small"><h2>{stockForm.indent_id?'Issue fabric · #'+stockForm.indent_id:'Receive sample fabric'}</h2>{#if error}<p class="form-error" role="alert">{error}</p>{/if}<label>Fabric<select bind:value={stockForm.material_id}><option value="">Select…</option>{#each data.materials.filter((m:any)=>m.company_id===Number(stockForm.company_id)) as m}<option value={m.id}>{m.code}</option>{/each}</select></label><label>Metres<input type="number" min="0.001" step="0.001" bind:value={stockForm.metres}/></label>{#if !stockForm.indent_id}<label>Receipt / DC reference<input bind:value={stockForm.reference}/></label>{/if}<footer><button class="button primary" disabled={busy} onclick={stockSave}>Save stock movement</button><button class="button secondary" disabled={busy} onclick={()=>stockForm=null}>Cancel</button></footer></div></div>{/if}
{#if detail}<div class="sample-print" aria-hidden="true">{#if printMode==='indent'}{#each printPieces as piece}<section class="print-sheet"><header><img src="/logo.png" alt="Euro Suits"/><div><h1>EURO SUITS · SAMPLE REQUEST</h1><h2>Indent #{piece.id} · {piece.size} · {piece.colour}</h2><p>SR-{detail.record.id} · {companies.find(c=>c.id===detail.record.company_id)?.name} · {piece.status}</p><p>Buyer: {detail.record.buyer_name} · Merchant: {detail.record.merchant}</p></div></header><div class="print-fields">{#each fields as [key,title]}{#if detail.record.profile[key]}<div><strong>{title}</strong> {key.includes('material_id')?material(detail.record.profile[key]):detail.record.profile[key]}</div>{/if}{/each}</div><h3>Sample BOM</h3><table><thead><tr><th>Group / component</th><th>Reference</th><th>Qty / unit</th><th>Colour / size / thread / remarks</th></tr></thead><tbody>{#each detail.record.bom as b}<tr><td>{b.group} / {b.component}</td><td>{b.reference||''}</td><td>{b.quantity||''} {b.unit||''}</td><td>{[b.colour,b.size,b.ticket,b.thread_position,b.shade,b.placement,b.remarks].filter(Boolean).join(' · ')}</td></tr>{/each}</tbody></table><p>{#each detail.issues.filter((i:any)=>i.indent_id===piece.id) as issue}DC: SDC-{String(issue.id).padStart(7,'0')} · {issue.code} · {Math.abs(Number(issue.metres))} m {/each}</p><h3>Production, audit and handover</h3><div class="print-fields">{#each Object.entries(piece.production) as [k,v]}{#if v}<div><strong>{label(k)}</strong> {String(v)}</div>{/if}{/each}</div></section>{/each}{:else}{#each layoutPages as boxes,index}<section class="print-sheet"><h1>EURO SUITS · SAMPLE LAYOUT</h1><p>SR-{detail.record.id} · {detail.record.profile.buyer_style} · EST {detail.record.profile.est} · Page {index+1}</p><div class="swatch-grid">{#each Array.from({length:6}) as _,i}<div><strong>{boxes[i]?.group||''} · {boxes[i]?.component||'Swatch'}</strong><p>Reference: {boxes[i]?.reference||''}</p><p>Colour: {boxes[i]?.colour||''} · Qty: {boxes[i]?.quantity||''}</p><small>Attach swatch here</small></div>{/each}</div></section>{/each}{/if}</div>{/if}
<style>
 .samples{background:#fff;border:1px solid #c5d3da;border-radius:14px;padding:24px}.samples header,.sample-dialog header,.piece header{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:20px}h2{font-size:22px}h3{margin:24px 0 12px}p{line-height:1.5}.actions{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.table-scroll{overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px;border-bottom:1px solid #ccd8dd}small{display:block}label{display:flex;flex-direction:column;gap:7px;font-size:14px;font-weight:700;color:#10202b}input,select,textarea{width:100%;background:#eff5fa;color:#101820;border:1px solid #aebfc9;border-radius:7px;min-height:42px;padding:10px;font-size:14px;font-weight:600}textarea{resize:vertical}.search{max-width:460px;margin:20px 0}.sample-overlay{position:fixed;inset:0;z-index:120;background:#10263699;display:grid;place-items:center;padding:22px}.sample-dialog{background:#eaf2ee;color:#14222c;max-width:1180px;width:100%;max-height:92vh;overflow:auto;padding:28px;border-radius:16px;box-shadow:0 20px 80px #0004;font-size:14px}.sample-dialog>header{position:sticky;top:-28px;z-index:5;background:#eaf2ee;margin:-28px -28px 20px;padding:14px 28px;border-bottom:1px solid #bccdc5;align-items:center}.sample-dialog>header h2{font-size:18px;margin:0}.sample-dialog>header .eyebrow{display:none}.form-grid,.details-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.wide{grid-column:1/-1}.option-line{display:flex;gap:6px}.variant{display:flex;align-items:end;gap:12px;margin:16px 0}.variant label{flex:1}.bom-row{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;border:1px solid #b9cdc1;border-radius:10px;padding:16px;margin:14px 0;background:#f7faf8}.inline-editor,.review{padding:18px;border:2px solid #36857a;margin:20px 0;background:#f5faf8;border-radius:10px}.inline-editor button,.review button{margin:10px 8px 0 0}footer{display:flex;gap:12px;justify-content:flex-end;padding-top:24px}.piece{border:1px solid #b4c7c1;background:#f8faf9;padding:18px;border-radius:10px;margin:18px 0}.details-grid{margin:18px 0}.details-grid strong,.details-grid span{display:block;overflow-wrap:anywhere;white-space:pre-wrap}.details-grid strong{font-size:12px;text-transform:uppercase;margin-bottom:5px}details{margin-top:20px}summary{cursor:pointer;font-weight:700}.small{max-width:540px}.small label{margin:16px 0}.top{z-index:130}.sample-print{display:none}@media(max-width:760px){.sample-overlay{padding:6px}.sample-dialog{padding:18px}.sample-dialog>header{top:-18px;margin:-18px -18px 18px;padding:12px 18px}.form-grid,.details-grid{grid-template-columns:1fr}.bom-row{grid-template-columns:repeat(2,minmax(0,1fr))}.variant{flex-wrap:wrap}.variant label{min-width:120px}.samples header{flex-direction:column}}
 @page{size:A4;margin:8mm}@media print{:global(body *){visibility:hidden!important}:global(.sample-print),:global(.sample-print *){visibility:visible!important}.sample-print{display:block;position:absolute;top:0;left:0;width:100%;background:#fff;color:#000;font-size:10px}.print-sheet{break-after:page;padding:0;min-height:0}.print-sheet:last-child{break-after:auto}.print-sheet header{display:flex;gap:14px;border-bottom:2px solid #000}.print-sheet img{width:55px;height:55px;object-fit:contain}.print-sheet h1{font-size:18px}.print-sheet h2{font-size:15px}.print-fields{display:grid;grid-template-columns:1fr 1fr;gap:5px;margin:12px 0;overflow-wrap:anywhere}.print-sheet th,.print-sheet td{padding:4px;border:1px solid #888;font-size:9px}.print-sheet tr{break-inside:avoid}.swatch-grid{display:grid;grid-template-columns:1fr 1fr;gap:8mm}.swatch-grid>div{height:70mm;border:1px solid #333;padding:6mm}.swatch-grid small{margin-top:20mm;color:#555}}
</style>
